-- Rollback of seo-m2-bts-army-level-test.sql (generated by apps/quiz/scripts/build-team-quiz-sql.mjs).
-- Removes the Team quiz "BTS ARMY level test" while it is still a DRAFT, and gives back the two counters
-- its insert added (groups.quiz_count, the Team's profiles.total_quizzes_created). It refuses
-- to touch a published quiz: once published, it has plays and links, and removing it is a
-- product decision (status 'removed' through the admin tools), not a rollback.

begin;

do $guard$
begin
  if exists (select 1 from public.quizzes where slug = 'bts-army-level-test' and status <> 'draft') then
    raise exception 'quiz % is no longer a draft: not rolled back', 'bts-army-level-test';
  end if;
end
$guard$;

with gone as (
  delete from public.quizzes
  where slug = 'bts-army-level-test' and status = 'draft' and creator_id = '00000000-0000-0000-0000-000000000001'::uuid
  returning group_id, creator_id
),
g as (
  update public.groups set quiz_count = greatest(quiz_count - 1, 0)
  where id in (select group_id from gone)
  returning id
)
update public.profiles set total_quizzes_created = greatest(total_quizzes_created - 1, 0), updated_at = now()
where id in (select creator_id from gone);

commit;
